const items = $input.all();

const counters = {
  verified_examined: items.length,
  eligible: 0,
  ineligible_not_qualified: 0,
  ineligible_missing_business_name: 0,
  ineligible_missing_city: 0,
  ineligible_missing_state: 0,
  ineligible_missing_country: 0,
  ineligible_no_contact_path: 0
};

const eligible = [];

for (const item of items) {
  const lead = item.json || {};

  const businessName = String(lead.business_name || '').trim();
  const city = String(lead.city || '').trim();
  const state = String(lead.state || '').trim();
  const country = String(lead.country || '').trim();
  const hasWebsite = String(lead.website || '').trim() !== '';
  const hasPhone = String(lead.phone || '').trim() !== '';
  const hasContactPath = hasWebsite || hasPhone;
  const isQualified = String(lead.qualification_status || '').trim().toUpperCase() === 'QUALIFIED';

  if (!isQualified) {
    counters.ineligible_not_qualified += 1;
    continue;
  }
  if (!businessName) {
    counters.ineligible_missing_business_name += 1;
    continue;
  }
  if (!city) {
    counters.ineligible_missing_city += 1;
    continue;
  }
  if (!state) {
    counters.ineligible_missing_state += 1;
    continue;
  }
  if (!country) {
    counters.ineligible_missing_country += 1;
    continue;
  }
  if (!hasContactPath) {
    counters.ineligible_no_contact_path += 1;
    continue;
  }

  eligible.push(item);
  counters.eligible += 1;
}

if (eligible.length === 0) {
  return [{
    json: {
      _noNewApproved: true,
      _message: 'No new eligible leads for Approved Outreach',
      _control: counters
    }
  }];
}

return eligible.map((item) => ({
  json: Object.assign({}, item.json, { _control: counters })
}));

const approvedItems = $input.all();
const eligibleItems = $('Filter Eligible Leads').all();

const filterCounters = {};
for (const item of eligibleItems) {
  const control = (item.json || {})._control;
  if (control && typeof control === 'object') Object.assign(filterCounters, control);
}

const existingIds = new Set();
for (const item of approvedItems) {
  const id = String((item.json || {}).lead_id || '').trim();
  if (id) existingIds.add(id);
}

const eligible = eligibleItems.filter((item) => !((item.json || {})._noNewApproved === true));

const counters = {
  eligible_incoming: eligible.length,
  already_approved: 0,
  duplicate_in_batch: 0,
  newly_approved: 0
};

if (eligible.length === 0) {
  return [{
    json: {
      _noNewApproved: true,
      _message: 'No new eligible leads for Approved Outreach',
      _control: Object.assign({}, filterCounters, counters)
    }
  }];
}

const seenThisRun = new Set();
const newRows = [];

for (const item of eligible) {
  const lead = item.json || {};
  const leadId = String(lead.lead_id || '').trim();

  if (!leadId) {
    counters.duplicate_in_batch += 1;
    continue;
  }
  if (existingIds.has(leadId)) {
    counters.already_approved += 1;
    continue;
  }
  if (seenThisRun.has(leadId)) {
    counters.duplicate_in_batch += 1;
    continue;
  }

  seenThisRun.add(leadId);
  newRows.push(item);
  counters.newly_approved += 1;
}

if (newRows.length === 0) {
  return [{
    json: {
      _noNewApproved: true,
      _message: 'All eligible leads are already in Approved Outreach',
      _control: Object.assign({}, filterCounters, counters)
    }
  }];
}

return newRows.map((item) => ({
  json: Object.assign({}, item.json, { _control: Object.assign({}, filterCounters, counters) })
}));

const items = $input.all();

const isNoOp =
  items.length === 1 &&
  items[0].json &&
  items[0].json._noNewApproved === true;

if (isNoOp) {
  return items;
}

const approvedAt = new Date().toISOString();

return items.map((item) => {
  const lead = item.json || {};

  return {
    json: {
      lead_id: String(lead.lead_id || '').trim(),
      business_name: String(lead.business_name || '').trim(),
      niche: String(lead.niche || '').trim(),
      city: String(lead.city || '').trim(),
      state: String(lead.state || '').trim(),
      country: String(lead.country || '').trim(),
      website: String(lead.website || '').trim(),
      phone: String(lead.phone || '').trim(),
      email: '',
      contact_name: '',
      contact_title: '',
      email_source: '',
      email_verified: '',
      contact_form: '',
      linkedin_url: '',
      lead_score: lead.score ?? '',
      qualification_status: String(lead.qualification_status || '').trim(),
      outreach_channel: '',
      outreach_status: 'not_ready',
      approved_at: approvedAt,
      notes: ''
    }
  };
});
